customCSS:
@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@500&display=swap');

body {
  background: #0a0f1c;
  color: #d7f7ff;
  font-family: 'Orbitron', sans-serif;
}

body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: linear-gradient(#00ff99 1px, transparent 1px),
                    linear-gradient(90deg, #00ff99 1px, transparent 1px);
  background-size: 50px 50px;
  opacity: 0.05;
  z-index: -1;
}

h2 {
  font-size: 1.4rem !important;
  text-transform: uppercase;
  color: #00f6ff;
  text-shadow: 0 0 8px #00f6ff, 0 0 16px #00f6ff, 0 0 24px #00f6ff;
  margin-bottom: 10px;
  transition: text-shadow 0.3s ease-in-out;
}

h2:hover {
  animation: glowPulse 1.5s infinite alternate;
}

@keyframes glowPulse {
  0% { text-shadow: 0 0 8px #00f6ff, 0 0 16px #00f6ff, 0 0 24px #00f6ff; }
  100% { text-shadow: 0 0 16px #00f6ff, 0 0 32px #00f6ff, 0 0 48px #00f6ff; }
}

.card {
  background: #10141f;
  border: 2px solid #1b1b1b;
  border-radius: 14px;
  margin-bottom: 1rem;
  box-shadow: 0 0 20px rgba(0, 255, 111, 0.15);
  transition: box-shadow 0.3s ease-in-out;
}
.card:hover {
  box-shadow: 0 0 20px rgba(0, 255, 111, 0.5), 0 0 40px rgba(0, 255, 111, 0.3);
}

.monitor-title {
  color: #d2eaff;
  font-size: 1.1rem;
  font-weight: bold;
}

.tag {
  font-weight: bold;
  padding: 3px 8px;
  border-radius: 8px;
  color: #fff;
  text-shadow: 0 0 6px rgba(0,0,0,0.5);
  display: inline-block;
  transition: transform 0.3s, box-shadow 0.3s;
}
.tag:hover {
  transform: scale(1.1);
  animation: tagPulse 1.2s infinite alternate;
}

@keyframes tagPulse {
  0% { box-shadow: 0 0 8px currentColor, 0 0 16px currentColor; }
  100% { box-shadow: 0 0 16px currentColor, 0 0 32px currentColor; }
}

.tag[data-tag="Core"] { background-color: #ff8a00; color: #fff; }
.tag[data-tag="Pi"] { background-color: #ff0033; }
.tag[data-tag="Services"] { background-color: #00ff88; }
.tag[data-tag="Home"] { background-color: #007bff; }
.tag[data-tag="Infrastructure"] { background-color: #666; }
.tag[data-tag="Health"] { background-color: #ff33cc; }
.tag[data-tag="System"] { background-color: #aa66ff; }

.badge {
  background: #000;
  border: 1px solid #00ff88;
  color: #00ff88;
  font-weight: bold;
  padding: 4px 8px;
  border-radius: 6px;
  box-shadow: 0 0 10px #00ff88;
  transition: transform 0.3s, box-shadow 0.3s;
}
.badge:hover {
  transform: scale(1.1);
  box-shadow: 0 0 16px #00ff88, 0 0 32px #00ff88;
}

.progress-bar {
  background-color: #00ff8c !important;
  box-shadow: 0 0 8px #00ff8c, 0 0 16px #00ff8c;
  border-radius: 6px;
}

.status-ok {
  color: #00ff88;
  font-weight: bold;
  text-shadow: 0 0 10px #00ff88, 0 0 20px #00ff88;
}
